package br.com.gestao.sale; import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="sale_items") public class SaleItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(optional=false) private Sale sale; private Long productId; private String productName; private Integer quantity; @Column(precision=12,scale=2) private BigDecimal unitPrice; @Column(precision=12,scale=2) private BigDecimal subtotal; public SaleItem(){} public SaleItem(Long productId,String productName,Integer quantity,BigDecimal unitPrice){this.productId=productId;this.productName=productName;this.quantity=quantity;this.unitPrice=unitPrice;this.subtotal=unitPrice.multiply(BigDecimal.valueOf(quantity));} public void setSale(Sale s){sale=s;} public Long getId(){return id;} public Long getProductId(){return productId;} public String getProductName(){return productName;} public Integer getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getSubtotal(){return subtotal;}}
